public static void boxTransfer(BlockPos to, BlockPos from, ChainConveyorBlockEntity be) {
    Iterator<ChainConveyorPackage> iterator = be.getLoopingPackages().iterator();
    while (iterator.hasNext()) {
        ChainConveyorPackage chainConveyorPackage = iterator.next();
        chainConveyorPackage.chainPosition = 0.0f;
        be.addTravellingPackage(chainConveyorPackage, to.m_121996_((Vec3i)from));
        iterator.remove();
    }
}

